package com.fabio.aether;
import android.app.Instrumentation;import android.content.Intent;import android.os.Bundle;
public class GameTest extends Instrumentation {int count;void check(boolean b,String s){if(!b)throw new AssertionError(s);count++;android.util.Log.i("AetherTest","PASS "+s);}public void onCreate(Bundle b){super.onCreate(b);start();}public void onStart(){Bundle result=new Bundle();try{final MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(()->{MainActivity.Game g=a.game;check(g.pass(20.5f,20.5f),"spawn livre");g.x=20.5f;g.y=20.5f;g.fx=0;g.fy=-1;g.map[20][19]=2;int c=g.crystal;g.mine();check(g.crystal==c+1&&g.map[20][19]==0,"mineracao concede cristal");int st=g.stone;g.build();check(g.stone==st-1&&g.map[20][19]==3,"construcao consome pedra");g.move(0,-.6f);check(g.y==20.5f,"colisao impede atravessar bloco");g.map[20][19]=0;g.mobs.clear();MainActivity.Game.Mob mob=g.new Mob(20.5f,19.5f,false);g.mobs.add(mob);g.attackCd=0;g.attack();check(mob.hp<35,"espada causa dano");float hp=mob.hp;g.attack();check(mob.hp==hp,"cooldown impede spam");g.dashCd=0;g.dash();check(g.inv>0&&g.dashTime>0,"dash concede esquiva");g.hp=40;g.potions=1;g.heal();check(g.hp==85&&g.potions==0,"pocao cura e consome");int lv=g.level;g.xp=Rules.xpNeed(lv);g.checkLevel();check(g.level==lv+1&&g.hp==100,"level up restaura vida");g.crystal=8;g.won=false;g.update(0);check(g.won,"missao conclui sem guardiao e com cristais");g.save();MainActivity.Game loaded=a.new Game();check(loaded.crystal==8&&loaded.won&&loaded.level==g.level,"save persiste progresso");check(loaded.mobs.isEmpty(),"guardiao derrotado nao reaparece");g.hp=0;g.update(0);check(g.hp==100&&g.x==20.5f&&g.y==20.5f,"derrota retorna ao acampamento");a.getPreferences(0).edit().clear().commit();g.started=false;});result.putString("stream","OK: "+count+" testes Android de integracao aprovados\n");finish(-1,result);}catch(Throwable t){result.putString("stream","FAIL: "+t.toString());finish(0,result);}}}
